"""V5 screen compositions. Story facts and supplied image files remain in data.py."""
from pathlib import Path
from html import escape as e
import json
import data as d

ROOT=Path(__file__).resolve().parents[1]
LABELS={'home':'가게','characters':'인물','rules':'시술 안내','treatment':'시술실','city':'베일하운','start':'시작'}
FOCUS=[51,84,75,80,11]

def arrow(back=False):
    return '<svg class="arrow" viewBox="0 0 36 20" aria-hidden="true"><path d="'+('M34 10H2M10 2l-8 8 8 8' if back else 'M2 10h32M26 2l8 8-8 8')+'"/></svg>'

def action(label,href=None,attrs='',cls=''):
    tag='a' if href else 'button'
    return f'<{tag} class="action {cls}" '+(f'href="{e(href)}" ' if href else '')+f'{attrs}><span>{label}</span>{arrow()}</{tag}>'

def picture(src,alt='',cls='',priority=False):
    return f'<img src="{src}" alt="{e(alt)}" class="{cls}" '+('fetchpriority="high"' if priority else 'loading="lazy"')+'>'

def heading(kicker,title):
    return f'<div class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1></div>'

def entrance():
    return f'''<section class="title-screen"><div class="title-art" data-parallax>{picture('assets/art/title-v5.webp',priority=True)}</div><canvas id="motes" aria-hidden="true"></canvas><div class="title-copy"><p class="eyebrow">VEILHAUN</p><h1><span>골목</span><span>시술소</span></h1><div class="entry-controls">{action('입장하기',attrs='id="enter"',cls='primary')}<p>만 19세 이상만 이용할 수 있습니다.</p></div></div><p class="title-credit">문창놈 작품</p></section>'''

def home():
    routes=[('characters','인물','직원과 손님'),('rules','시술 안내','결 · 향유 · 관계'),('city','베일하운','도시와 골목'),('start','시작하기','개업 · 자유모드')]
    previews={'characters':d.CHARACTERS[0]['portrait'],'rules':'assets/art/perfumery.webp','city':'assets/art/atlas.webp','start':'assets/art/title-v5.webp'}
    links=''.join(f'<a href="{slug}.html" data-room-preview="{previews[slug]}"><span class="route-number">0{i}</span><span class="route-title">{name}<small>{sub}</small></span>{arrow()}</a>' for i,(slug,name,sub) in enumerate(routes,1))
    menus=''.join(f'<li><span class="list-number">0{i}</span><h3>{e(n)}<small>{e(t)}</small></h3><strong>{e(p)}</strong></li>' for i,(n,p,t) in enumerate(d.MENUS,1))
    reservations=''.join(f'<li>{e(r.get("time",""))} · {e(r.get("name",""))} · {e(r.get("menu",""))}</li>' for r in d.CONFIG['RESERVATIONS']) or '<li>등록된 예약이 없습니다.</li>'
    return f'''<section class="house-stage"><div class="house-art">{picture('assets/art/title-v5.webp','',priority=True)}<img id="room-preview" alt=""></div><div class="house-title"><p class="eyebrow">VEILHAUN</p><h1>골목<br>시술소</h1><a class="scroll-link" href="#reception">접수대 살펴보기 <span>↓</span></a></div><nav class="house-routes" aria-label="주요 페이지">{links}</nav><div class="house-caption"><span>베일하운 뒷골목</span><span>영업중</span></div></section><section class="reception-content section-wrap" id="reception"><div class="section-title"><span class="eyebrow">RECEPTION</span><h2>접수대</h2></div><div class="reception-columns"><div><h3 class="subheading">시술 메뉴</h3><ol class="service-list">{menus}</ol><p class="muted">{e(d.COPY['currency'])}</p>{action('시술실 보기','treatment.html')}</div><div class="reception-notes"><h3 class="subheading">오늘의 예약</h3><ul>{reservations}</ul><h3 class="subheading">골목의 평판</h3><ol class="reputation">{''.join(f'<li class="{"current" if i==0 else ""}">{e(x)}</li>' for i,x in enumerate(d.REPUTATION))}</ol><button id="partition" class="text-link">칸막이 너머 듣기 {arrow()}</button><p id="voice" class="voice" aria-live="polite" hidden></p><button class="text-link" data-open="rumor-dialog" data-rumor-open>골목 소문 {arrow()}</button></div></div></section>'''

def characters():
    ch=d.CHARACTERS[0]
    choices=''.join(f'<button class="cast-choice" data-cast="{i}" data-group="{e(x["group"])}" aria-pressed="{str(i==0).lower()}" style="--focus:{FOCUS[i]}%"><span class="cast-thumb">{picture(x["portrait"],"",priority=i<2)}</span><span><small>0{i+1} / {e(x["group"])}</small><strong>{e(x["name"])}</strong></span></button>' for i,x in enumerate(d.CHARACTERS))
    return f'''<section class="cast-stage"><div class="cast-art" data-parallax>{picture(ch['portrait'],ch['name'],'cast-image',True)}</div><div class="cast-info"><div class="cast-heading"><p class="eyebrow">CHARACTERS</p><span>인물</span><span id="cast-count">01 / 05</span></div><div class="cast-details" aria-live="polite"><p id="cast-meta">{ch['race']} · {ch['age']} · {ch['group']}</p><h1 id="cast-name">{ch['name']}</h1><p id="cast-role">{ch['role']}</p><p id="cast-quote">“{ch['hook']}”</p>{action('인물 기록 보기','char/'+ch['slug']+'.html',attrs='id="cast-link"',cls='primary')}</div><div class="cast-step"><button data-cast-step="-1" aria-label="이전 인물">{arrow(True)}</button><button data-cast-step="1" aria-label="다음 인물">{arrow()}</button></div></div></section><nav class="cast-selector" aria-label="인물 선택">{choices}</nav>'''

def chart(ch):
    i=d.CHARACTERS.index(ch)
    tabs=''.join(f'<button data-expression="{n}" aria-pressed="{str(n==0).lower()}">{e(name)}</button>' for n,name in enumerate(d.EXPRESSIONS))
    reactions=ch['reactions'].split(' / ')
    vals=[ch['collapse'],reactions[0],reactions[1].split(': ',1)[-1],reactions[2].split(': ',1)[-1]]
    details=''.join(f'<div><dt>{e(d.COPY[k])}</dt><dd>{e(v)}</dd></div>' for k,v in zip(['collapse','stop','ask','jealous'],vals))
    relations=''.join(f'<li>{e(x)}</li>' for x in d.RELATIONS if ch['name'] in x)
    return f'''<section class="profile-stage"><div class="profile-art"><button class="portrait-zoom" aria-label="그림 크게 보기">{picture('../'+ch['portrait'],ch['name'],'study-image',True)}</button></div><div class="profile-heading"><a class="back-link" href="../characters.html">{arrow(True)} 인물 목록</a><p class="eyebrow">CHARACTER {ch['code']}</p><h1>{e(ch['name'])}</h1><p class="profile-meta">{e(ch['race'])} · {ch['age']} · {e(ch['group'])}</p><p>{e(ch['role'])}</p><blockquote>“{e(ch['hook'])}”</blockquote><a class="scroll-link" href="#record">인물 기록 <span>↓</span></a></div></section><section class="expression-bar"><nav class="expression-tabs" aria-label="감정 선택">{tabs}</nav><div class="image-pager"><button id="expr-prev" aria-label="이전 표정">{arrow(True)}</button><span id="expression-title" aria-live="polite">첫등장</span><button id="expr-next" aria-label="다음 표정">{arrow()}</button></div><div id="variant-thumbs" aria-label="표정 변형"></div></section><article class="character-record section-wrap" id="record"><section class="record-intro reveal"><div class="section-title"><span class="eyebrow">PROFILE</span><h2>인물 기록</h2></div><p>{e(ch['description'])}</p></section><div class="record-grid"><section class="record-map reveal"><h3 class="subheading">결 지도</h3><p>{e(ch['knots'])}</p><div class="text-tabs"><button data-facing="front" aria-pressed="true">정면</button><button data-facing="back" aria-pressed="false">뒷면</button></div><div class="body-map"><svg viewBox="0 0 200 300" aria-label="결 자리 실루엣" role="img"><circle cx="100" cy="46" r="23"/><path d="M85 70Q60 74 52 94L36 163Q37 174 47 169L68 112 70 174 59 265Q63 279 74 269L99 193 125 269Q136 277 140 265L129 174 131 112 153 169Q164 174 164 161L147 94Q137 74 115 70Z"/></svg><div id="map-dots"></div></div><p id="knot-label" aria-live="polite">{e(d.COPY['knots'])}</p></section><section class="record-boundary reveal"><h3 class="subheading">첫 허용선</h3><ol class="boundary-list">{''.join(f'<li class="{"unlocked" if n<(2 if ch["code"]=="E" else 1) else ""}"><span>0{n+1}</span>{e(x)}</li>' for n,x in enumerate(d.BOUNDARIES))}</ol><dl class="reactions">{details}</dl></section></div><section class="record-quotes reveal">{''.join('<blockquote>“'+e(q)+'”</blockquote>' for q in ch['quotes'])}</section><div class="record-grid record-notes"><section><h3 class="subheading">외형과 말투</h3><p>{e(ch['appearance'])}</p><p>{e(ch['speech'])}</p></section><section><h3 class="subheading">관계</h3><ul>{relations}</ul></section></div><nav class="record-pagination">{action(d.CHARACTERS[(i-1)%5]['name'],d.CHARACTERS[(i-1)%5]['slug']+'.html')}{action(d.CHARACTERS[(i+1)%5]['name'],d.CHARACTERS[(i+1)%5]['slug']+'.html')}</nav></article>'''

def rules():
    depths=''.join(f'<li><span>0{i}</span><div><h3>{e(n)}</h3><p>{e(t)}</p></div></li>' for i,(n,t) in enumerate(d.DEPTHS,1))
    return f'''<div class="rules-backdrop">{picture('assets/art/title-v5.webp','',priority=True)}</div><div class="guide-layout"><aside class="guide-index">{heading('TREATMENT GUIDE','시술 안내')}<nav aria-label="안내 목차"><button data-book="0" aria-pressed="true"><span>01</span>결의 깊이</button><button data-book="1" aria-pressed="false"><span>02</span>달아오름</button><button data-book="2" aria-pressed="false"><span>03</span>허용선과 관계</button></nav><a href="treatment.html" class="text-link">시술실 보기 {arrow()}</a></aside><div class="guide-content"><div class="book-leaf"><section data-book-page="0"><p class="eyebrow">01 / THE KNOTS</p><h2>결의 깊이</h2><p class="lead">{e(d.COPY['knots_definition'])}</p><ol class="depths">{depths}</ol><p class="progress-text">{e(d.COPY['knots_progress'])}</p></section><section data-book-page="1" hidden><p class="eyebrow">02 / WARMTH</p><h2>달아오름</h2><div class="heat-flame" aria-hidden="true"><i></i><i></i><i></i></div><nav class="heat-steps" aria-label="달아오름 단계">{''.join(f'<button data-heat="{i}" aria-pressed="{str(i==0).lower()}"><small>0{i+1}</small>{e(x)}</button>' for i,x in enumerate(d.HEAT))}</nav><p class="heat-label">평온</p></section><section data-book-page="2" hidden><p class="eyebrow">03 / RELATIONSHIPS</p><h2>허용선과 관계</h2><h3 class="subheading">허용선</h3><ol class="note-stages">{''.join('<li><span>0'+str(i+1)+'</span>'+e(x)+'</li>' for i,x in enumerate(d.BOUNDARIES))}</ol><h3 class="subheading">관계</h3><p class="relation-stages">{' · '.join(d.RELATION_STAGES)}</p></section></div><div class="book-pager"><button data-book-step="-1" aria-label="안내 이전 장">{arrow(True)}</button><span id="book-count">01 / 03</span><button data-book-step="1" aria-label="안내 다음 장">{arrow()}</button></div></div></div><section class="oil-section section-wrap"><div class="section-title"><span class="eyebrow">PERFUMERY</span><h2>향유</h2></div><div class="oil-layout"><div class="bottle-shelf">{''.join(f'<button class="bottle {key}" data-oil="{key}" aria-pressed="false"><span class="bottle-art" aria-hidden="true"></span><span>{name}</span></button>' for key,name in [('calm','진정'),('warm','온열'),('unknown','?')])}</div><p id="oil-note" aria-live="polite">향유를 선택하세요.</p></div></section>'''

def city():
    p=d.PLACES[0]
    places=''.join(f'<button data-place="{i}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span>{e(x["name"])}</button>' for i,x in enumerate(d.PLACES))
    return f'''<section class="city-stage">{heading('WORLD / VEILHAUN','베일하운')}<div class="city-window">{picture('images/B/'+p['code']+'.webp',p['name'],'city-picture',True)}</div><div class="city-bottom"><div class="place-story" aria-live="polite"><span id="place-number">01</span><div><h2 id="place-name">{e(p['name'])}</h2><p id="place-text">{e(p['text'])}</p><p id="place-guest"></p></div></div><div class="place-step"><button data-place-step="-1" aria-label="이전 장소">{arrow(True)}</button><button data-place-step="1" aria-label="다음 장소">{arrow()}</button></div></div><nav class="place-index" aria-label="도시 장소">{places}</nav></section>'''

def treatment():
    link=action('들어가기',d.CONFIG['MASA_URL'],cls='primary') if d.CONFIG['MASA_URL'] else '<p class="unavailable">시술 체험은 준비 중입니다.</p>'
    return f'''<section class="treatment-stage"><div class="treatment-scene">{picture('assets/art/title-v5.webp','시술실',priority=True)}</div><div class="drapery left" aria-hidden="true"></div><div class="drapery right" aria-hidden="true"></div><div class="treatment-title"><p class="eyebrow">TREATMENT ROOM</p><h1>시술실</h1><p>{e(d.COPY['treatment_note'])}</p>{action('커튼 열기',attrs='id="draw-curtain" aria-expanded="false"',cls='primary')}<div class="treatment-destination" hidden>{link}</div></div></section>'''

def start():
    modes=''.join(f'<button data-mode="{key}" aria-pressed="{str(i==0).lower()}"><span class="mode-number">0{i+1}</span><span><strong>{e(name)}</strong><small>{e(desc)}</small></span>{arrow()}</button>' for i,(key,name,desc) in enumerate(d.MODES))
    link=action('작품으로 들어가기',d.CONFIG['CRACK_URL'],cls='primary') if d.CONFIG['CRACK_URL'] else '<p class="unavailable">작품 링크 준비 중</p>'
    return f'''<div class="opening-background">{picture('assets/art/title-v5.webp','',priority=True)}</div><div class="opening-wrap section-wrap">{heading('NEW STORY','시작하기')}<div class="opening-layout"><section><nav class="opening-modes" aria-label="시작 모드">{modes}</nav><form id="free-form" hidden><label>경과일<input name="day" type="number" min="0" max="99999" value="0"></label><label>소지금<input name="money" maxlength="120"></label><label>평판<select name="rep">{''.join('<option>'+e(x)+'</option>' for x in d.REPUTATION)}</select></label><label class="full">아는 인물과 관계<textarea name="relations" maxlength="1000"></textarea></label>{action('출발 상태 복사',attrs='type="submit"',cls='primary')}<output id="copy-status" aria-live="polite"></output><textarea id="copy-fallback" aria-label="복사할 출발 상태" readonly hidden></textarea></form></section><section class="opening-preview"><p class="eyebrow">PREVIEW</p><h2>출발 장면</h2><div class="sample-panorama">{picture('images/B/R.webp','접수대')}</div><div id="prologue"><p>프롤로그 미등록</p></div><details><summary>정보창 형식</summary><pre>{e(d.STATUS_TEMPLATE)}</pre></details><details><summary>플레이 안내</summary><p>{e(d.COPY['unwritten'])}</p></details>{link}</section></div></div>'''

def write_page(filename,page,body,char=None):
    prefix='../' if '/' in filename else ''
    label=char['name'] if char else LABELS.get(page,'입구')
    payload=dict(config=d.CONFIG,characters=d.CHARACTERS,rumors=d.RUMORS,voices=d.VOICES,places=d.PLACES,expressions=d.EXPRESSIONS,copy=d.COPY,knots=d.KNOT_MAP,page=page,character=char['slug'] if char else None,prefix=prefix)
    for ch in payload['characters']:
        ch['gallery']=[[ch['portrait']] if (ROOT/ch['portrait']).is_file() else []]+[[f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp" for n in range(g['start'],g['end']+1) if (ROOT/f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp").is_file()] for g in d.EXPRESSION_GROUPS[1:]]
    nav=''.join(f'<a href="{prefix}{slug}.html" '+('aria-current="page"' if page==slug or page=='chart' and slug=='characters' else '')+f'><span>0{i}</span>{LABELS[slug]}</a>' for i,(slug,name,en,bg) in enumerate(d.ROOMS,1))
    topnav=''.join(f'<a href="{prefix}{slug}.html" '+('aria-current="page"' if page==slug or page=='chart' and slug=='characters' else '')+f'>{LABELS[slug]}</a>' for slug in ['home','characters','rules','city','start'])
    guard='' if page=='index' else f'<script src="{prefix}assets/guard.js?v=5"></script>'
    html=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111310"><meta name="description" content="골목 시술소. 베일하운의 인물과 시술, 도시를 둘러보세요."><title>{e(label)} | 골목 시술소</title>{guard}<link rel="icon" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/fonts/pretendard/pretendard.css"><link rel="stylesheet" href="{prefix}assets/fonts/hahmlet/hahmlet.css"><link rel="stylesheet" href="{prefix}assets/cinema.css?v=5"><script id="site-data" type="application/json">{json.dumps(payload,ensure_ascii=False).replace('</','<\\/')}</script><script defer src="{prefix}assets/cinema.js?v=5"></script></head><body class="page-{page}"><a href="#main" class="skip-link">본문으로 건너뛰기</a><header class="site-header"><a class="brand" href="{prefix}{'index' if page=='index' else 'home'}.html">골목 시술소</a><nav class="desktop-nav" aria-label="주 메뉴">{topnav}</nav><button id="menu-open" aria-label="전체 메뉴" aria-haspopup="dialog"><span>메뉴</span><i aria-hidden="true"></i></button></header><main id="main">{body}</main><footer class="site-footer"><a href="{prefix}home.html" class="footer-brand">골목 시술소</a><span class="author">글 · 설정 {e(d.CONFIG['AUTHOR'])}</span><button id="sound" aria-pressed="false">효과음</button><button id="bell">소문 듣기</button><a href="{prefix}index.html" data-exit>입구로</a></footer><dialog id="directory" class="directory" aria-label="전체 메뉴"><form method="dialog"><button class="close-text">닫기 <span>×</span></button></form><div class="directory-heading"><p class="eyebrow">VEILHAUN</p><h2>골목 시술소</h2></div><nav>{nav}</nav><p class="directory-foot">글 · 설정 {e(d.CONFIG['AUTHOR'])}</p></dialog><dialog id="art-lightbox" class="lightbox" aria-label="그림 크게 보기"><form method="dialog"><button class="close-text">닫기 <span>×</span></button></form><img alt=""></dialog><dialog id="rumor-dialog" class="rumor-dialog"><form method="dialog"><button class="close-text">닫기 <span>×</span></button></form><p class="eyebrow">AROUND THE ALLEY</p><h2>골목 소문</h2><p id="rumor-text" aria-live="polite"></p>{action('다음 소문',attrs='id="rumor-next"')}</dialog><div class="page-wipe" aria-hidden="true"></div></body></html>'''
    if any(x in html for x in ['\u2013','\u2014']): raise ValueError('Forbidden dash in '+filename)
    dest=ROOT/filename
    dest.parent.mkdir(exist_ok=True)
    dest.write_text(html,encoding='utf-8')
